/**
 * sw.js - the service worker that makes JEE ASCENT work with no network.
 *
 * The precache list is generated by tools/build-sw.js into precache.js, so it
 * can never drift out of sync with the files actually on disk. Bump the list
 * by re-running `npm run sw`.
 *
 * Strategies:
 *   navigation      -> app shell from cache, network refresh in the background
 *   same-origin GET -> stale-while-revalidate
 *   cross-origin    -> network only (there are none, by design)
 */

importScripts('./precache.js');

const VERSION = self.__PRECACHE_VERSION || 'dev';
const CACHE = `jee-ascent-${VERSION}`;
const SHELL = './index.html';
const OFFLINE = './offline.html';

/* ------------------------------------------------------------------ */

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    const urls = self.__PRECACHE || [];
    // Add individually: one 404 must not abort the whole install.
    const results = await Promise.allSettled(urls.map((u) => cache.add(new Request(u, { cache: 'reload' }))));
    const failed = results
      .map((r, i) => (r.status === 'rejected' ? urls[i] : null))
      .filter(Boolean);
    if (failed.length) console.warn('[sw] could not precache', failed);
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter((k) => k.startsWith('jee-ascent-') && k !== CACHE).map((k) => caches.delete(k)));
    await self.clients.claim();
  })());
});

self.addEventListener('message', (event) => {
  if (event.data === 'skip-waiting') self.skipWaiting();
});

/* ------------------------------------------------------------------ */

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;

  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;   // nothing external ships with this app

  // Navigations always resolve to the single-page shell.
  if (req.mode === 'navigate') {
    event.respondWith((async () => {
      const cache = await caches.open(CACHE);
      const cached = await cache.match(SHELL);
      if (cached) {
        // Refresh the shell in the background for next time.
        fetch(req).then((res) => { if (res.ok) cache.put(SHELL, res.clone()); }).catch(() => {});
        return cached;
      }
      try {
        const res = await fetch(req);
        if (res.ok) cache.put(SHELL, res.clone());
        return res;
      } catch {
        return (await cache.match(OFFLINE)) || new Response('Offline', { status: 503 });
      }
    })());
    return;
  }

  // Everything else: serve from cache immediately, revalidate behind it.
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const cached = await cache.match(req);

    const network = fetch(req).then((res) => {
      if (res && res.ok && res.type === 'basic') cache.put(req, res.clone());
      return res;
    }).catch(() => null);

    if (cached) return cached;

    const res = await network;
    if (res) return res;

    // Nothing cached and no network.
    if (req.destination === 'document') {
      return (await cache.match(OFFLINE)) || new Response('Offline', { status: 503 });
    }
    return new Response('', { status: 504, statusText: 'Offline' });
  })());
});
